 const form=document.querySelector('#modelForm'),provider=form.elements.provider,applyPreset=()=>{const p=presets[provider.value];form.elements.base_url.value=p.base_url;form.elements.model.value=p.model;form.elements.api_key.disabled=provider.value==='mock';form.elements.api_key_ref.disabled=provider.value==='mock'};provider.onchange=applyPreset;applyPreset();
