 form.onsubmit=async e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(form)),body=draft();body.id=raw.id||undefined;body.name=raw.name;const saved=await api('/api/models/profiles',{method:'POST',body});form.elements.api_key.value='';await api('/api/models/assignments',{method:'POST',body:{assignments:{global:saved.id}}});toast('模型连接已保存并设为全局默认；密钥仅驻留后端内存。');await models();};
