 document.querySelectorAll('.test-profile').forEach(b=>b.onclick=async()=>{const x=await api('/api/model/test',{method:'POST',body:{profile_id:b.dataset.id}});document.querySelector('#modelResult').innerHTML=connectionResult(x)});
 document.querySelectorAll('.edit-profile').forEach(b=>b.onclick=()=>{const p=profiles[Number(b.dataset.index)];form.elements.id.value=p.id;form.elements.name.value=p.name;form.elements.provider.value=p.config.provider;form.elements.base_url.value=p.config.base_url;form.elements.model.value=p.config.model;form.elements.api_key_ref.value=p.config.api_key_ref||'';for(const k of ['temperature','max_tokens','timeout_ms','retries'])form.elements[k].value=p.config[k];form.elements.api_key.value='';form.elements.api_key.disabled=p.config.provider==='mock';form.elements.api_key_ref.disabled=p.config.provider==='mock';form.scrollIntoView({behavior:'smooth'});form.elements.name.focus()});
