 document.querySelector('#assignmentForm').onsubmit=async e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.target)),clean=Object.fromEntries(Object.entries(raw).filter(([,v])=>v));await api('/api/models/assignments',{method:'POST',body:{assignments:clean}});toast('模型分配已立即应用到后续运行。');await models();};
