async function setupMedLoCoMoLatestPanel(){const form=document.querySelector('#benchForm'),target=document.querySelector('#benchResult');if(!form||!target||location.hash.slice(1)!=='medlocomo')return;target.insertAdjacentHTML('beforebegin','<div id="medLoCoMoLatestExperiment" class="span12"><div class="card"><div class="loading">正在按 Overall、Single、Cross 整理最新实验数据…</div></div></div>');const box=document.querySelector('#medLoCoMoLatestExperiment');const refresh=async()=>{if(!box?.isConnected||location.hash.slice(1)!=='medlocomo')return;const patientId=String(form.elements.patient_id.value||'16957952'),queryType=String(form.elements.query_type.value||''),experiments=await api('/api/experiments/summaries?benchmark=medlocomo'),sources=medLoCoMoLatestSources(experiments,patientId,queryType);box.innerHTML=medLoCoMoLatestExperimentsView(sources,patientId,queryType);box.querySelectorAll('.open-latest-medlocomo').forEach(button=>button.addEventListener('click',async event=>{const id=event.currentTarget.dataset.id,render=async()=>{const detail=await api(`/api/experiments/${id}/view`);target.innerHTML=experimentView(detail);bindExperimentDetail(detail,target,render);await refresh()};await render()}));if(medLoCoMoLatestTimer){clearTimeout(medLoCoMoLatestTimer);medLoCoMoLatestTimer=null}if(Object.values(sources).some(item=>item&&['running','paused'].includes(item.status)))medLoCoMoLatestTimer=setTimeout(()=>refresh(),800)};const followLatest=()=>{if(medLoCoMoLatestTimer)clearTimeout(medLoCoMoLatestTimer);medLoCoMoLatestTimer=setTimeout(()=>refresh(),500)};form.elements.patient_id.addEventListener('change',refresh);form.elements.query_type.addEventListener('change',refresh);form.addEventListener('submit',followLatest);form.addEventListener('experiment-launched',followLatest);await refresh()}
