 const form=document.querySelector('#benchForm'),target=document.querySelector('#benchResult'),startButton=form.querySelector('button:not([type])'),scoreCurrentStateButton=form.querySelector('#scoreCurrentState'),values=()=>{const x=Object.fromEntries(new FormData(form));for(const k of ['persona_id','start_session','session_count','task','index','session','max_queries'])if(x[k]!==undefined&&x[k]!=='')x[k]=Number(x[k]);else delete x[k];if(x.noise!==undefined)x.noise=x.noise==='true';for(const key of ['clinical_safety_gate','understanding_clarification_gate','preference_feasibility_gate'])x[key]=Boolean(form.elements[key]?.checked);return x};
